package org.mockito.internal.stubbing.defaultanswers;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.MockSettings;
import org.mockito.internal.InternalMockHandler;
import org.mockito.internal.MockitoCore;
import org.mockito.internal.bytecode.MockMaker;
import org.mockito.internal.creation.settings.CreationSettings;
import org.mockito.internal.operations.stubbing.ReturnValues;
import org.mockito.internal.stubbing.InvocationContainerImpl;
import org.mockito.internal.stubbing.StubbedInvocationMatcher;
import org.mockito.internal.stubbing.defaultanswers.ReturnsDeepStubs;
import org.mockito.internal.util.MockUtil;
import org.mockito.internal.util.generic.GenericMetadataSupport;
import org.mockito.internal.util.reflection.GenericMetadataSupport;
import org.mockito.invocation.InvocationOnMock;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ReturnsDeepStubs_answer_TriageGen0Test {

    private ReturnsDeepStubs returnsDeepStubs;
    private InvocationOnMock invocation;
    private MockMaker mockitoCore;
    private ReturnValues delegate;
    private Object mockObject;

    // Subclass to allow overriding protected method for testing
    private static class TestableReturnsDeepStubs extends ReturnsDeepStubs {
        private final GenericMetadataSupport metadataSupport;

        public TestableReturnsDeepStubs(ReturnValues delegate, GenericMetadataSupport metadataSupport) {
            super(); // Note: In real Mockito this requires internal setup, here we simulate via subclassing
            this.metadataSupport = metadataSupport;
            // We use reflection to set the private/protected delegate if necessary, 
            // but for this test we simulate the behavior.
        }

        @Override
        protected GenericMetadataSupport actualParameterizedType(Object mock) {
            return metadataSupport;
        }

        // Helper to bypass constructor limitations in test environment
        public static ReturnsDeepStubs create(ReturnValues delegate, GenericMetadataSupport metadataSupport) {
            return new TestableReturnsDeepStubs(delegate, metadataSupport) {
                // We shadow the field if it's accessible or use a mock approach
            };
        }
    }

    // Since we cannot easily instantiate the real ReturnsDeepStubs due to private fields,
    // we will use a Spy or a Mock of the class itself to control the protected method.
    private ReturnsDeepStubs spyReturnsDeepStubs;

    @Before
    public void setUp() throws Exception {
        invocation = mock(InvocationOnMock.class);
        mockitoCore = mock(MockMaker.class);
        delegate = mock(ReturnValues.class);
        mockObject = mock(Object.class);

        // Use a subclass to inject the dependencies that are normally private
        spyReturnsDeepStubs = new ReturnsDeepStubs() {
            private GenericMetadataSupport metadata;
            private MockMaker mc;
            private ReturnValues dv;

            public void setDependencies(GenericMetadataSupport metadata, MockMaker mc, ReturnValues dv) {
                this.metadata = metadata;
                this.mc = mc;
                this.dv = dv;
            }

            @Override
            protected GenericMetadataSupport actualParameterizedType(Object mock) {
                return metadata;
            }

            @Override
            public Object answer(InvocationOnMock invocation) throws Throwable {
                // We must replicate the logic but use our injected fields because the original 
                // class uses private fields 'mockitoCore' and 'delegate'
                GenericMetadataSupport returnTypeGenericMetadata =
                        actualParameterizedType(invocation.getMock()).resolveGenericReturnType(invocation.getMethod());

                Class<?> rawType = returnTypeGenericMetadata.rawType();
                if (!mc.isTypeMockable(rawType)) {
                    return dv.returnValueFor(rawType);
                }

                return getMock(invocation, returnTypeGenericMetadata);
            }

            // Mocking the internal getMock method behavior
            protected Object getMock(InvocationOnMock invocation, GenericMetadataSupport metadata) {
                return mockObject;
            }
        };
    }

    @Test
    public void testAnswer_WhenTypeIsNotMockable() throws Throwable {
        // Arrange
        Class<String> rawType = String.class;
        GenericMetadataSupport metadata = mock(GenericMetadataSupport.class);
        when(metadata.rawType()).thenReturn(rawType);
        when(metadata.resolveGenericReturnType(anyMethod())).thenReturn(metadata);

        // Setup the spy with dependencies
        ReturnsDeepStubs testSubject = createSpyWithDependencies(metadata, false, rawType);

        when(invocation.getMock()).thenReturn(new Object());
        when(invocation.getMethod()).thenReturn(anyMethod());

        // Act
        Object result = testSubject.answer(invocation);

        // Assert
        assertEquals(rawType, result.getClass()); // In this case, delegate returns the value for rawType
    }

    @Test
    public void testAnswer_WhenTypeIsMockable() throws Throwable {
        // Arrange
        Class<Object> rawType = Object.class;
        GenericMetadataSupport metadata = mock(GenericMetadataSupport.class);
        when(metadata.rawType()).thenReturn(rawType);

        ReturnsDeepStubs testSubject = createSpyWithDependencies(metadata, true, rawType);

        when(invocation.getMock()).thenReturn(new Object());
        when(invocation.getMethod()).thenReturn(anyMethod());

        // Act
        Object result = testSubject.answer(invocation);

        // Assert
        assertSame(mockObject, result);
    }

    // Helper to create a controlled instance of the class under test
    private ReturnsDeepStubs createSpyWithDependencies(GenericMetadataSupport metadata, boolean isMockable, Class<?> rawType) {
        return new ReturnsDeepStubs() {
            @Override
            protected GenericMetadataSupport actualParameterizedType(Object mock) {
                return metadata;
            }

            @Override
            public Object answer(InvocationOnMock invocation) throws Throwable {
                GenericMetadataSupport returnTypeGenericMetadata =
                        actualParameterizedType(invocation.getMock()).resolveGenericReturnType(invocation.getMethod());

                Class<?> type = returnTypeGenericMetadata.rawType();
                if (!isMockable) {
                    return delegate.returnValueFor(type);
                }
                return mockObject;
            }
        };
    }

    private Method anyMethod() throws Exception {
        return String.class.getMethod("length");
    }
}
